UPDATE public.badges AS b SET
 name=p.item->>'name',description=p.item->>'condition',
 requirement=jsonb_set(coalesce(b.requirement,'{}'::jsonb),'{rule}',p.item,true)
FROM patches p WHERE b.badge_key=p.item->>'key';

-- The prior migration rebuilt numeric player_stats but left cached best-roll
-- and rarest-run strings at their old values. Reconstruct from converted Dailies.
WITH corrected AS (
 SELECT p.user_id, best.best_roll_label AS best_label,
 rare.rarity_odds AS rare_odds, rare.rarity_label AS rare_label
 FROM public.player_stats p
 JOIN LATERAL (
  SELECT d.best_roll_label FROM public.daily_runs d
  WHERE d.user_id=p.user_id AND d.is_test=false
  ORDER BY d.best_roll_points DESC NULLS LAST,d.id LIMIT 1
 ) best ON true
 JOIN LATERAL (
  SELECT d.rarity_odds,d.rarity_label FROM public.daily_runs d
  WHERE d.user_id=p.user_id AND d.is_test=false
  ORDER BY d.rarity_odds DESC NULLS LAST,d.score DESC,d.id LIMIT 1
 ) rare ON true
)
UPDATE public.player_stats p SET
 best_roll_label=c.best_label,rarest_odds=c.rare_odds,
 rarest_label=c.rare_label,updated_at=now()
FROM corrected c WHERE p.user_id=c.user_id
 AND (p.best_roll_label IS DISTINCT FROM c.best_label
  OR p.rarest_odds IS DISTINCT FROM c.rare_odds
  OR p.rarest_label IS DISTINCT FROM c.rare_label);

DO $verify$
DECLARE bad integer;
BEGIN
 SELECT count(*) INTO bad FROM public.badges b
 JOIN public.crilo_v3_badge_stage s ON s.badge_key=b.badge_key
 WHERE s.display_name IS DISTINCT FROM b.name
 OR s.description IS DISTINCT FROM b.description
 OR (s.rule->>'condition') IS DISTINCT FROM (b.requirement->'rule'->>'condition');
 IF bad<>0 THEN RAISE EXCEPTION 'Badge display labels inconsistent: %',bad; END IF;
 SELECT count(*) INTO bad FROM public.player_stats p
 WHERE EXISTS(SELECT 1 FROM public.daily_runs d WHERE d.user_id=p.user_id AND d.is_test=false)
 AND (
 p.best_roll_label IS DISTINCT FROM (SELECT d.best_roll_label FROM public.daily_runs d WHERE d.user_id=p.user_id AND d.is_test=false ORDER BY d.best_roll_points DESC NULLS LAST,d.id LIMIT 1)
 OR p.rarest_label IS DISTINCT FROM (SELECT d.rarity_label FROM public.daily_runs d WHERE d.user_id=p.user_id AND d.is_test=false ORDER BY d.rarity_odds DESC NULLS LAST,d.score DESC,d.id LIMIT 1)
 );
 IF bad<>0 THEN RAISE EXCEPTION 'Cached player labels inconsistent: %',bad; END IF;
END $verify$;
